          fhir_medicationRequest_dosageInstruction_timing_repeat.bounds = create('Period') as fhir_medicationRequest_dosageInstruction_timing_boundsPeriod then IVLTSPeriod(cda_effectiveTime_IVLTS_noWidth,fhir_medicationRequest_dosageInstruction_timing_boundsPeriod);

          // Einnahmedauer: Width-Element vorhanden
          cda_effectiveTime: IVL_TS as cda_effectiveTime_IVLTS_width where ($this.width.exists() and $this.low.exists().not() and $this.high.exists().not()) ->
          fhir_medicationRequest_dosageInstruction_timing_repeat.bounds = create('Duration') as fhir_medicationRequest_dosageInstruction_timing_boundsDuration then {
            // effectiveTime/width
            cda_effectiveTime_IVLTS_width.width as cda_effectiveTime_IVLTS_width_width then PQQuantity(cda_effectiveTime_IVLTS_width_width,fhir_medicationRequest_dosageInstruction_timing_boundsDuration);
          };

          // Zeitelement Dosierungsvarianten 1 und 3 (EIN Wochentag)
          cda_effectiveTime: PIVL_TS as cda_effectiveTime_PIVLTS where ($this.period.exists() or $this.phase.exists()) then {
            // Zeitraum und Periodeneinheit der Dosis
            // Einnahmezeitraum Period -> medicationRequest.dosageInstruction.timing.period und medicationRequest.dosageInstruction.timing.periodUnit
            cda_effectiveTime_PIVLTS.period as cda_effectiveTime_PIVLTS_period ->
            fhir_medicationRequest_dosageInstruction_timing_repeat.period = (cda_effectiveTime_PIVLTS_period.value),
            fhir_medicationRequest_dosageInstruction_timing_repeat.periodUnit = (cda_effectiveTime_PIVLTS_period.unit);
            // Erstes Datum des Wochentages nach Einnahmebeginn
            cda_effectiveTime_PIVLTS.phase as cda_effectiveTime_PIVLTS_phase ->
            fhir_medicationRequest_dosageInstruction_timing.event as fhir_medicationRequest_dosageInstruction_timing_event then TSDateTime(cda_effectiveTime_PIVLTS_phase, fhir_medicationRequest_dosageInstruction_timing_event);
