          fhir_medicationRequest_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_doseQuantity,fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity);
        
          // Art der Anwendung der Arznei
